import pandas as pd,numpy as np
from sklearn.model_selection import RepeatedKFold,cross_validate
from sklearn.compose import ColumnTransformer
from sklearn.preprocessing import OneHotEncoder,SplineTransformer,StandardScaler,PolynomialFeatures,FunctionTransformer
from sklearn.pipeline import make_pipeline
from sklearn.linear_model import RidgeCV,ElasticNetCV
D=pd.read_csv('alloy_pair_constrained_train.csv'); cats=['heat_treatment','route']; comps=['C','Mn','Si','Cr','Ni','Mo','V','Nb','Co','Al','Ti','Cu']; nums=comps+['solutionizing_temp','aging_temp','aging_time','cooling_rate']; X=D[nums+cats];y=D.target
cv=RepeatedKFold(n_splits=5,n_repeats=3,random_state=42)
for scope,inter in [('comp',comps),('all',nums)]:
 for deg in [2]:
  pre=ColumnTransformer([('spl',SplineTransformer(n_knots=3,degree=3,include_bias=False),nums),('inter',make_pipeline(StandardScaler(),PolynomialFeatures(2,interaction_only=True,include_bias=False)),inter),('cat',OneHotEncoder(drop='first',sparse_output=False),cats)])
  m=make_pipeline(pre,StandardScaler(),RidgeCV(alphas=np.logspace(-2,5,40)))
  s=cross_validate(m,X,y,cv=cv,scoring={'mae':'neg_mean_absolute_error','rmse':'neg_root_mean_squared_error','r2':'r2'},n_jobs=-1)
  print(scope,'raw_inter MAE %.2f RMSE %.2f R2 %.3f'%(-s['test_mae'].mean(),-s['test_rmse'].mean(),s['test_r2'].mean()))
# tensor product spline basis interactions only among each original pair. custom transformer
class TensorPairs:
 def __init__(self,columns):self.columns=columns
 def fit(self,X,y=None):
  self.s=[]
  for c in self.columns:self.s.append(SplineTransformer(n_knots=3,degree=2,include_bias=False).fit(np.asarray(X[[c]])))
  return self
 def transform(self,X):
  B=[s.transform(np.asarray(X[[c]])) for s,c in zip(self.s,self.columns)]; out=[]
  for i in range(len(B)):
   for j in range(i+1,len(B)):out.append((B[i][:,:,None]*B[j][:,None,:]).reshape(len(X),-1))
  return np.hstack(out)
 def get_params(self,deep=True):return {'columns':self.columns}
 def set_params(self,**p):self.columns=p.get('columns',self.columns);return self
for scope,inter in [('comp',comps)]:
 pre=ColumnTransformer([('spl',SplineTransformer(n_knots=3,degree=3,include_bias=False),nums),('tensor',TensorPairs(inter),inter),('cat',OneHotEncoder(drop='first',sparse_output=False),cats)])
 m=make_pipeline(pre,StandardScaler(),RidgeCV(alphas=np.logspace(0,6,35)))
 s=cross_validate(m,X,y,cv=cv,scoring={'mae':'neg_mean_absolute_error','rmse':'neg_root_mean_squared_error','r2':'r2'},n_jobs=-1)
 print(scope,'tensor MAE %.2f RMSE %.2f R2 %.3f'%(-s['test_mae'].mean(),-s['test_rmse'].mean(),s['test_r2'].mean()))
